//! Fixture-driven tests for the login, generated by the real Python (`app/tools/oracle/login_vectors.py`).
//!
//! `crypto.json` and `headers.json` are checked value by value; `flows.json` drives the whole
//! `AppleAccount` against a scripted HTTP server built from the recorded replies, and every request
//! the Rust sends is compared byte for byte with the Python's. No test here talks to Apple.

use std::collections::BTreeMap;
use std::sync::Arc;
use std::time::Duration;

use apple_core::http::Http;
use apple_core::login::account::AppleAccount;
use apple_core::login::crypto;
use apple_core::login::device::{
    AccountInfo, DeviceIdentity, LoginDevice, LoginEndpoints, LoginResult, LoginState,
    SecondFactorMethod,
};
use apple_core::login::messages;
use apple_core::login::srp::SrpClient;
use apple_core::login::{AnisetteSource, BoxFuture};
use serde_json::Value;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::TcpListener;
use tokio::sync::Mutex;

fn fixture(name: &str) -> Value {
    let path = format!(
        "{}/../../app/android/app/src/test/resources/fixtures/{name}",
        env!("CARGO_MANIFEST_DIR")
    );
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {path}: {e}"));
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("parse {path}: {e}"))
}

fn b64(s: &str) -> Vec<u8> {
    use base64::Engine as _;
    base64::engine::general_purpose::STANDARD.decode(s).unwrap()
}

fn hexvec(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

#[test]
fn crypto_vectors() {
    let doc = fixture("login/crypto.json");
    let salt = b64("qjrRbspqiZ4VvtVffdTTow==");

    for case in doc["pbkdf2"].as_array().unwrap() {
        let password = case["password"].as_str().unwrap();
        let sp = case["sp"].as_str().unwrap();
        let iterations = case["iterations"].as_u64().unwrap() as u32;
        let digest = crypto::password_digest(password.as_bytes());
        let p = crypto::derive_password(&digest, &salt, iterations, sp).unwrap();
        assert_eq!(crypto::hex(&p), case["P"].as_str().unwrap(), "pbkdf2 {}", case);
    }

    for case in doc["spd"].as_array().unwrap() {
        let key = hexvec(case["K"].as_str().unwrap());
        let ct = b64(case["spd"].as_str().unwrap());
        let plain = crypto::decrypt_spd(&key, &ct).unwrap();
        assert_eq!(plain, b64(case["plaintext"].as_str().unwrap()), "spd {}", case["name"]);
        // The prolog rule must let an XML plist missing its prolog parse too.
        let decoded = apple_core::plist::parse(&crypto::with_plist_prolog(&plain)).unwrap();
        assert_eq!(decoded.get("adsid").and_then(|v| v.as_str()), Some("000123-05-synthetic"));
        assert_eq!(decoded.get("blob").and_then(|v| v.as_data()), Some(&b"\x00\x01binary"[..]));
    }
}

#[test]
fn srp_vectors() {
    let doc = fixture("login/crypto.json");
    for case in doc["srp"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let username = case["username"].as_str().unwrap();
        let a = hexvec(case["a"].as_str().unwrap());
        let salt = b64(case["salt"].as_str().unwrap());
        let b = hexvec(case["B"].as_str().unwrap());
        let p = hexvec(case["P"].as_str().unwrap());
        let mut srp = SrpClient::new(username, &a);
        assert_eq!(crypto::hex(&srp.public_a()), case["A"].as_str().unwrap(), "A {name}");
        let m1 = srp.process_challenge(&salt, &b, &p).expect("challenge");
        assert_eq!(crypto::hex(&m1), case["M1"].as_str().unwrap(), "M1 {name}");
        assert!(srp.verify_session(Some(&hexvec(case["M2"].as_str().unwrap()))), "M2 {name}");
        assert_eq!(crypto::hex(srp.session_key().unwrap()), case["K"].as_str().unwrap(), "K {name}");
    }
}

#[test]
fn header_vectors() {
    let doc = fixture("login/headers.json");
    let identity = DeviceIdentity::mac_13_1();

    let anisette: BTreeMap<String, String> = doc["get_headers"]
        .as_object()
        .unwrap()
        .iter()
        .map(|(k, v)| (k.clone(), v.as_str().unwrap().to_string()))
        .collect();
    let cpd = messages::cpd(&anisette);
    let expected = doc["get_cpd"].as_object().unwrap();
    for (k, v) in expected {
        let got = match cpd.get(k) {
            Some(apple_core::plist::Value::String(s)) => Value::String(s.clone()),
            Some(apple_core::plist::Value::Boolean(b)) => Value::Bool(*b),
            other => panic!("unexpected cpd value {other:?}"),
        };
        assert_eq!(&got, v, "cpd {k}");
    }

    let from_headers = apple_core::login::login_anisette_headers(&anisette).unwrap();
    assert_eq!(from_headers, anisette);

    let identity_token = crypto::identity_token("000123-05-synthetic", "SYNTH-IDMS");
    assert_eq!(identity_token, doc["identity_token"]["value"].as_str().unwrap());
    assert_eq!(messages::sms_request_body(2), doc["sms_request_body"].as_str().unwrap());
    assert_eq!(messages::sms_submit_body(2, "123456"), doc["sms_submit_body"].as_str().unwrap());

    for phone in doc["phones"].as_array().unwrap() {
        let methods = messages::extract_phone_numbers(phone["html"].as_str().unwrap()).unwrap();
        let got: Vec<Value> = methods
            .iter()
            .map(|m| match m {
                SecondFactorMethod::TrustedDevice => serde_json::json!({"kind": "trusted_device"}),
                SecondFactorMethod::Sms { phone_number_id, phone_number } => {
                    serde_json::json!({"kind": "sms", "id": phone_number_id, "number": phone_number})
                }
            })
            .collect();
        let expected: Vec<Value> = phone["numbers"]
            .as_array()
            .unwrap()
            .iter()
            .map(|n| {
                let id = n.get("id").and_then(|v| v.as_i64()).filter(|v| *v != 0).unwrap_or(-1);
                let number = n
                    .get("numberWithDialCode")
                    .and_then(|v| v.as_str())
                    .filter(|s| !s.is_empty())
                    .unwrap_or("-");
                serde_json::json!({"kind": "sms", "id": id, "number": number})
            })
            .collect();
        assert_eq!(Value::Array(got), Value::Array(expected), "phones {}", phone["name"]);
    }
    assert!(messages::extract_phone_numbers("<html><body>no script</body></html>").is_err());

    assert_eq!(identity.client_info("com.apple.AuthKit/1 (com.apple.akd/1.0)"), doc["client_akd"]);
    assert_eq!(identity.user_agent("com.apple.iCloudHelper/282"), doc["icloud_helper_user_agent"]);
    assert_eq!(identity.client_info("com.apple.AOSKit/282 (com.apple.accountsd/113)"), doc["accountsd_client_info"]);
}

// --------------------------------------------------------------------------- whole flows

struct FakeAnisette {
    headers: BTreeMap<String, String>,
    sims: Mutex<Vec<String>>,
}

impl AnisetteSource for FakeAnisette {
    fn headers(&self) -> BoxFuture<'_, apple_core::Result<BTreeMap<String, String>>> {
        let h = self.headers.clone();
        Box::pin(async move { Ok(h) })
    }
    fn resync<'a>(&'a self, sim: &'a str) -> BoxFuture<'a, apple_core::Result<()>> {
        Box::pin(async move {
            self.sims.lock().await.push(sim.to_string());
            Ok(())
        })
    }
}

struct Exchange {
    path: String,
    response_status: u16,
    response_headers: Vec<(String, String)>,
    response_body: Vec<u8>,
    consumed: bool,
}

#[derive(Clone, Debug)]
struct Received {
    method: String,
    path: String,
    headers: Vec<(String, String)>,
    body: Vec<u8>,
}

async fn mock_server(exchanges: Vec<Exchange>) -> (String, Arc<Mutex<Vec<Exchange>>>, Arc<Mutex<Vec<Received>>>) {
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let addr = listener.local_addr().unwrap();
    let store = Arc::new(Mutex::new(exchanges));
    let received = Arc::new(Mutex::new(Vec::new()));
    let (s, r) = (store.clone(), received.clone());
    tokio::spawn(async move {
        loop {
            let Ok((mut socket, _)) = listener.accept().await else { break };
            let (s, r) = (s.clone(), r.clone());
            tokio::spawn(async move {
                let Some(req) = read_request(&mut socket).await else { return };
                let mut guard = s.lock().await;
                let chosen = guard.iter_mut().find(|e| !e.consumed && e.path == req.path);
                let Some(ex) = chosen else {
                    let _ = socket
                        .write_all(b"HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\nConnection: close\r\n\r\n")
                        .await;
                    return;
                };
                ex.consumed = true;
                let status = ex.response_status;
                let headers = ex.response_headers.clone();
                let body = ex.response_body.clone();
                drop(guard);
                r.lock().await.push(req);
                let reason = if status == 200 { "OK" } else { "Error" };
                let mut out = format!("HTTP/1.1 {status} {reason}\r\n");
                for (k, v) in headers {
                    out.push_str(&format!("{k}: {v}\r\n"));
                }
                out.push_str(&format!("Content-Length: {}\r\nConnection: close\r\n\r\n", body.len()));
                let _ = socket.write_all(out.as_bytes()).await;
                let _ = socket.write_all(&body).await;
                let _ = socket.flush().await;
            });
        }
    });
    (format!("http://{addr}"), store, received)
}

async fn read_request(socket: &mut tokio::net::TcpStream) -> Option<Received> {
    let mut buf = Vec::new();
    let mut tmp = [0u8; 4096];
    loop {
        let n = socket.read(&mut tmp).await.ok()?;
        if n == 0 {
            return None;
        }
        buf.extend_from_slice(&tmp[..n]);
        if let Some(pos) = find_double_crlf(&buf) {
            let head = String::from_utf8_lossy(&buf[..pos]).to_string();
            let mut lines = head.lines();
            let request_line = lines.next()?;
            let mut parts = request_line.split_whitespace();
            let method = parts.next()?.to_string();
            let path = parts.next()?.to_string();
            let mut headers = Vec::new();
            let mut content_length = 0usize;
            for line in lines {
                if let Some((k, v)) = line.split_once(':') {
                    let k = k.trim().to_string();
                    let v = v.trim().to_string();
                    if k.eq_ignore_ascii_case("content-length") {
                        content_length = v.parse().unwrap_or(0);
                    }
                    headers.push((k, v));
                }
            }
            let mut body = buf[pos + 4..].to_vec();
            while body.len() < content_length {
                let n = socket.read(&mut tmp).await.ok()?;
                if n == 0 {
                    break;
                }
                body.extend_from_slice(&tmp[..n]);
            }
            body.truncate(content_length);
            return Some(Received { method, path, headers, body });
        }
    }
}

fn find_double_crlf(buf: &[u8]) -> Option<usize> {
    buf.windows(4).position(|w| w == b"\r\n\r\n")
}

fn exchange_from(v: &Value) -> Exchange {
    let url = v["url"].as_str().unwrap();
    let path = url.split("://").nth(1).unwrap().split_once('/').map(|(_, p)| format!("/{p}")).unwrap();
    let mut response_headers = Vec::new();
    for (k, val) in v["response"]["headers"].as_object().unwrap() {
        response_headers.push((k.clone(), val.as_str().unwrap().to_string()));
    }
    Exchange {
        path,
        response_status: v["response"]["status"].as_u64().unwrap() as u16,
        response_headers,
        response_body: b64(v["response"]["body"].as_str().unwrap()),
        consumed: false,
    }
}

#[tokio::test(flavor = "multi_thread")]
async fn whole_flows_match_the_python() {
    let doc = fixture("login/flows.json");
    for flow in doc.as_array().unwrap() {
        run_flow(flow).await;
    }
}

async fn run_flow(flow: &Value) {
    let name = flow["name"].as_str().unwrap();
    let exchanges: Vec<Exchange> = flow["exchanges"].as_array().unwrap().iter().map(exchange_from).collect();
    let expected: Vec<Value> = flow["exchanges"].as_array().unwrap().clone();
    let (origin, store, received) = mock_server(exchanges).await;
    let no_reuse = std::collections::BTreeSet::new();
    let endpoints = LoginEndpoints::under(&origin, no_reuse);

    let anisette = flow["anisette"].as_object().unwrap();
    let headers: BTreeMap<String, String> = anisette
        .iter()
        .map(|(k, v)| (k.clone(), v.as_str().unwrap().to_string()))
        .collect();
    let anisette = Arc::new(FakeAnisette { headers, sims: Mutex::new(Vec::new()) });

    let device = LoginDevice {
        local_user_uuid: "8F2C6A1E5B7D49C3A0E1F2D3C4B5A697".into(),
        device_id: "00006000-0A1B2C3D4E5F6071".into(),
        serial: Some("C02SYNTH0001".into()),
        identity: DeviceIdentity::mac_13_1(),
        cloud_kit_device_uuid: "00006000-0A1B-2C3D-4E5F-6071".into(),
    };

    let a_values: Vec<Vec<u8>> = flow["a_values"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| hexvec(v.as_str().unwrap()))
        .collect();
    let cursor = Arc::new(Mutex::new(std::collections::VecDeque::from(a_values.clone())));
    let used = Arc::new(Mutex::new(Vec::new()));
    let used2 = used.clone();
    let ephemeral = move || {
        let mut c = cursor.try_lock().unwrap();
        let v = c.pop_front().expect("more authentications than recorded a values");
        used2.try_lock().unwrap().push(v.clone());
        v
    };

    let http = Http::new(Duration::from_secs(10)).unwrap();
    let account = AppleAccount::new(device, anisette.clone(), endpoints, http).with_ephemeral(ephemeral);

    let username = flow["username"].as_str().unwrap();
    let mut password = flow["password"].as_str().unwrap().as_bytes().to_vec();
    let outcome = flow["outcome"].as_object().unwrap();

    let result = account.login(username, &mut password, false).await;
    let mut final_state = match result {
        Ok(LoginResult::SignedIn) => LoginState::LoggedIn,
        Ok(LoginResult::SecondFactorRequired(_)) => {
            // The fixture does not record `second_factor`; the outcome does.
            let list_methods = outcome.get("methods").is_some();
            let methods = if list_methods {
                Some(account.second_factor_methods().await.unwrap())
            } else {
                None
            };
            if let Some(methods) = &methods {
                let got: Vec<Value> = methods
                    .iter()
                    .map(|m| match m {
                        SecondFactorMethod::TrustedDevice => serde_json::json!({"kind": "trusted_device"}),
                        SecondFactorMethod::Sms { phone_number_id, phone_number } => {
                            serde_json::json!({"kind": "sms", "id": phone_number_id, "number": phone_number})
                        }
                    })
                    .collect();
                assert_eq!(Value::Array(got), outcome["methods"], "{name}: methods");
            }
            if outcome.get("trusted_device_2fa").and_then(|v| v.as_bool()) == Some(true) {
                account.request_trusted_device_code().await.unwrap();
                account.submit_trusted_device_code("123456").await.unwrap();
            } else {
                let methods = methods.as_ref().expect("an SMS flow lists methods");
                let sms: Vec<&SecondFactorMethod> = methods
                    .iter()
                    .filter(|m| matches!(m, SecondFactorMethod::Sms { .. }))
                    .collect();
                let method = sms[1];
                let id = match method {
                    SecondFactorMethod::Sms { phone_number_id, .. } => *phone_number_id,
                    _ => unreachable!(),
                };
                account.request_sms_code(id).await.unwrap();
                account.submit_sms_code(id, "123456").await.unwrap();
            }
            LoginState::LoggedIn
        }
        Err(e) => {
            if let Some(_expected_error) = outcome.get("error").and_then(|v| v.as_str()) {
                assert!(
                    e.to_string().contains("-22406") || matches!(e, apple_core::Error::Authentication(_)),
                    "{name}: expected an authentication error, got {e}"
                );
                return;
            }
            panic!("{name}: login failed: {e}");
        }
    };

    if outcome.get("request_pet").is_some() || outcome.get("pet").is_some() {
        let pet = account.request_pet().await.unwrap();
        assert_eq!(pet, outcome["pet"].as_str().unwrap(), "{name}: PET");
        final_state = account.login_state().await;
        assert_eq!(final_state, LoginState::LoggedIn, "{name}: state after PET");
    }

    if let Some(expected) = outcome.get("dsid").and_then(|v| v.as_str()) {
        assert_eq!(
            account.dsid().await.unwrap_or_else(|e| panic!("{name}: dsid: {e}")),
            expected,
            "{name}: dsid"
        );
    }
    if let Some(expected) = outcome.get("adsid").and_then(|v| v.as_str()) {
        assert_eq!(account.adsid().await, expected, "{name}: adsid");
    }
    if let Some(expected) = outcome.get("account_name").and_then(|v| v.as_str()) {
        assert_eq!(account.account_name().await, expected, "{name}: account name");
    }
    if let Some(expected) = outcome.get("tokens").and_then(|v| v.as_object()) {
        for (k, v) in expected {
            assert_eq!(
                account.service_token(k).await.as_deref(),
                v.as_str(),
                "{name}: token {k}"
            );
        }
    }
    if let Some(expected) = outcome.get("idms_hb").and_then(|v| v.as_str()) {
        let saved = account.snapshot().await.unwrap();
        assert_eq!(saved.idms_hb.as_deref(), Some(expected), "{name}: idms_hb");
    }

    // Every request must be byte-identical to the Python's.
    let got = received.lock().await.clone();
    let received_exchanges = store.lock().await.len();
    assert_eq!(got.len(), expected.len(), "{name}: request count (server had {received_exchanges})");
    for (i, (req, exp)) in got.iter().zip(expected.iter()).enumerate() {
        assert_eq!(req.method, exp["method"].as_str().unwrap(), "{name}: request {i} method");
        let url = exp["url"].as_str().unwrap();
        let path = url.split("://").nth(1).unwrap().split_once('/').map(|(_, p)| format!("/{p}")).unwrap();
        assert_eq!(req.path, path, "{name}: request {i} path");
        let expected_body = b64(exp["body"].as_str().unwrap());
        if req.body != expected_body {
            eprintln!("== GOT ==\n{}\n== EXPECTED ==\n{}", String::from_utf8_lossy(&req.body), String::from_utf8_lossy(&expected_body));
        }
        assert_eq!(req.body, expected_body, "{name}: request {i} body");
        let expected_headers = exp["headers"].as_object().unwrap();
        for (k, v) in expected_headers {
            let got = req
                .headers
                .iter()
                .find(|(hk, _)| hk.eq_ignore_ascii_case(k))
                .map(|(_, v)| v.clone());
            assert_eq!(got.as_deref(), Some(v.as_str().unwrap()), "{name}: request {i} header {k}");
        }
        if let Some(ct) = exp["implied_content_type"].as_str() {
            let got = req
                .headers
                .iter()
                .find(|(hk, _)| hk.eq_ignore_ascii_case("content-type"))
                .map(|(_, v)| v.clone());
            assert_eq!(got.as_deref(), Some(ct), "{name}: request {i} content type");
        }
    }

    let sims = anisette.sims.lock().await.clone();
    let expected_sims: Vec<String> = flow["resync_sims"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap().to_string())
        .collect();
    assert_eq!(sims, expected_sims, "{name}: resync sims");

    // The fake ephemeral must not have been asked for more values than recorded.
    assert_eq!(used.lock().await.len(), a_values.len(), "{name}: a values used");
    let _ = final_state;
    let _ = AccountInfo::default();
}
